#include <iostream>
#include <vector>

int square(int x);                               // declaration
double average(const std::vector<int>& values);  // declaration

int main() {
    std::cout << square(12) << '\n';
    std::vector<int> marks{80, 92, 71};
    std::cout << average(marks) << '\n';
}

int square(int x) {                              // definition
    return x * x;
}

double average(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    int sum{};
    for (int v : values) sum += v;
    return static_cast<double>(sum) / values.size();
}

#include <iostream>
#include <string>

void describe(int n) {
    std::cout << "int " << n << '\n';
}

void describe(double d) {
    std::cout << "double " << d << '\n';
}

void describe(const std::string& s) {
    std::cout << "string \"" << s << "\"\n";
}

std::string greet(const std::string& name, const std::string& greeting = "Hello") {
    return greeting + ", " + name + "!";
}

int main() {
    describe(7);
    describe(7.5);
    describe(std::string{"seven"});
    std::cout << greet("Ada") << '\n';
    std::cout << greet("Ada", "Welcome back") << '\n';
}

#include <iostream>

constexpr long long factorial(int n) {
    return n <= 1 ? 1 : n * factorial(n - 1);
}

static_assert(factorial(5) == 120);   // verified by the compiler

int main() {
    constexpr long long f10 = factorial(10);   // computed at compile time
    std::cout << "10! = " << f10 << '\n';

    int n{};
    std::cout << "n: ";
    std::cin >> n;
    std::cout << n << "! = " << factorial(n) << '\n';   // computed at run time
}

#include <initializer_list>
#include <iostream>

[[nodiscard]] bool isLeap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

auto daysIn(int year) -> int {
    return isLeap(year) ? 366 : 365;
}

int main() {
    for (int year : {1900, 2000, 2024, 2026}) {
        std::cout << year << ": " << daysIn(year) << '\n';
    }
    isLeap(2024);   // result ignored: the compiler warns
}
